using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckTugOfWar {public sealed class TugProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsTug")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.TugProbe",false);UnityEditor.SessionState.SetBool("LWS.TugProbe",false);
#endif
 if(run){var g=new GameObject("Owned Mountain Tug actual-physics match acceptance");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<TugProbe>();}}
 TugMatch m;string folder,key,saved;bool had,restored;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool good,string label){log.AppendLine((good?"PASS ":"FAIL ")+label);if(!good)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("TugEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<TugMatch>("TruckTugOfWar");m=FindAnyObjectByType<TugMatch>();yield return null;key=m.PreferenceKey;had=SportsPrefs.HasKey(key);saved=SportsPrefs.GetString(key);for(int test=0;test<3;test++){m.SetupScreen();m.teamA=m.teamB=test==0?1:4;m.option=test==2?1:0;m.NormalizeSetup();m.AllBots();for(int i=0;i<m.setup.count;i++)m.setup.players[i].difficulty=(BowlingDifficulty)test;Check(m.StartMatch(),"actual NWH AI Tug match starts difficulty="+test+" teamSize="+m.teamA);Time.timeScale=6;float deadline=Time.realtimeSinceStartup+600,next=0,peakTension=0,peakSpeed=0,maxAdvantage=0;bool replayChecked=false,pauseChecked=false;int priorHeat=0;while(!m.Finished&&Time.realtimeSinceStartup<deadline&&m.Heat<25&&errors<10){peakTension=Mathf.Max(peakTension,m.Tension);maxAdvantage=Mathf.Max(maxAdvantage,Mathf.Abs(m.Advantage));for(int i=0;i<m.setup.count;i++)peakSpeed=Mathf.Max(peakSpeed,m.trucks[i].body.linearVelocity.magnitude);if(m.Heat!=priorHeat){priorHeat=m.Heat;log.AppendLine("ROUND "+m.Heat+" side0="+m.Side(0)+" wins="+string.Join(",",m.wins));}if(m.Stage==TugStage.Pull&&m.Clock>2&&!pauseChecked){m.Pause();var p=m.trucks[0].body.position;var v=m.trucks[0].body.linearVelocity;float clock=m.Clock;yield return new WaitForSecondsRealtime(.15f);Check(m.Paused&&p==m.trucks[0].body.position&&v==m.trucks[0].body.linearVelocity&&clock==m.Clock,"pause preserves physical rope/truck velocity/round clock");m.Resume();pauseChecked=true;}if(m.Stage==TugStage.Replay){if(!replayChecked){int[] wins=(int[])m.wins.Clone();m.ExtraAction("replayangle");m.ExtraAction("replayspeed");Check(m.replay.Angle==1&&m.replay.Speed==.5f,"actual recorded losing flight supports camera angle and slow motion");m.replay.Seek(Mathf.Max(0,m.replay.Duration-1));m.ExtraAction("replayrewind");Check(string.Join(",",wins)==string.Join(",",m.wins),"rewind cannot revoke or duplicate locked Tug result");replayChecked=true;}m.ExtraAction("replayskip");}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE test="+test+" heat="+m.Heat+" stage="+m.Stage+" clock="+m.Clock+" h0="+m.headers[0].position+" h1="+m.headers[1].position+" advantage="+m.Advantage+" tension="+m.Tension+" heaves="+m.Heaves+" peakSpeed="+peakSpeed+" errors="+errors);next=Time.realtimeSinceStartup+3;}yield return null;}Check(m.Finished&&m.Winner>=0&&m.wins[m.Winner]==3,"complete first-to-three actual physical match difficulty="+test);Check(peakTension>1&&peakSpeed>1&&maxAdvantage>.05f&&m.Heaves>0,"real joint tension, NWH movement, heaves and physical ground gain observed");Check(replayChecked&&pauseChecked,"replay and pause exercised within real match");log.AppendLine("MATCH difficulty="+test+" heats="+m.Heat+" draws="+m.Draws+" wins="+string.Join(",",m.wins)+" heaves="+m.Heaves+" peakTension="+peakTension+" peakSpeed="+peakSpeed+" maxAdvantage="+maxAdvantage);Time.timeScale=1;}
 m.SetupScreen();m.AllBots();Check(m.StartMatch()&&m.Heat==1&&m.wins[0]==0&&m.wins[1]==0&&m.Heaves==0&&Array.TrueForAll(m.fragments,f=>!f.Bursting),"rematch resets all wins/rope/header/fragments/heave state");m.SetupScreen();Restore();log.AppendLine("ERRORS="+errors+". Real NWH/PhysX joints and AI full matches, no injected wins; native batch is not human/hardware or rendered performance acceptance.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null)m.SetupScreen();if(key!=null){if(had)SportsPrefs.SetString(key,saved);else SportsPrefs.DeleteKey(key);SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
}}
